using System;
using System.Collections.Generic;
using System.IO;

namespace Maela
{
    internal enum SoundCue
    {
        JoinVoice, LeaveVoice, PeerJoined, PeerLeft, Mute, Unmute, Deafen, Undeafen, Message, Connected, Disconnected
    }

    /// <summary>
    /// mæla's sound effects, generated by a tiny built-in synth: no audio files, nothing to
    /// download or license. Every cue is a few soft bell-like notes (sine plus a quiet
    /// overtone, quick attack, exponential decay) with fades so nothing clicks, kept well
    /// below full volume. Output is 48 kHz mono 16-bit PCM, ready for the playback path.
    /// </summary>
    internal static class SoundFx
    {
        public const int SampleRate = 48000;
        // Loudness per kind of cue, as average (RMS) level so short bright sounds don't feel
        // louder than long soft ones. Big moments (join, connect) are clearest; small feedback
        // (mute, someone else joining, a message) sits quieter. Peaks are capped as well.
        private const double Big = 0.050;     // about -26 dBFS RMS
        private const double Medium = 0.038;  // about -28.5 dBFS RMS
        private const double Small = 0.030;   // about -30.5 dBFS RMS
        private const double PeakCap = 0.18;  // never above about -15 dBFS
        private const double LowPassHz = 3000.0;

        private static readonly Dictionary<SoundCue, byte[]> Cache = new Dictionary<SoundCue, byte[]>();

        /// <summary>16-bit little-endian PCM for a cue (cached after the first call).</summary>
        public static byte[] Render(SoundCue cue)
        {
            lock (Cache)
            {
                byte[] pcm;
                if (!Cache.TryGetValue(cue, out pcm))
                {
                    pcm = ToPcm(Synthesize(cue));
                    Cache[cue] = pcm;
                }
                return pcm;
            }
        }

        private static float[] Synthesize(SoundCue cue)
        {
            // Notes: (start seconds, frequency Hz, duration seconds, level 0..1, overtone 0..1)
            // Warm register (about 260-880 Hz): pleasant on any speaker, never piercing.
            switch (cue)
            {
                case SoundCue.JoinVoice:      // Rising two-note chime.
                    return Mix(Big, 0.55, Note(0.00, 523.3, 0.35, 0.8, 0.25), Note(0.09, 784.0, 0.45, 0.9, 0.25));
                case SoundCue.LeaveVoice:     // The same two notes, falling.
                    return Mix(Big, 0.55, Note(0.00, 784.0, 0.30, 0.8, 0.20), Note(0.09, 523.3, 0.45, 0.85, 0.20));
                case SoundCue.PeerJoined:     // Softer rising blip.
                    return Mix(Small, 0.40, Note(0.00, 587.3, 0.22, 0.55, 0.15), Note(0.07, 880.0, 0.30, 0.6, 0.15));
                case SoundCue.PeerLeft:       // Softer falling blip.
                    return Mix(Small, 0.40, Note(0.00, 880.0, 0.20, 0.5, 0.12), Note(0.07, 587.3, 0.30, 0.55, 0.12));
                case SoundCue.Mute:           // Two quick low ticks, going down.
                    return Mix(Medium, 0.25, Tick(0.00, 440.0, 0.6), Tick(0.07, 329.6, 0.65));
                case SoundCue.Unmute:         // Two quick low ticks, going up.
                    return Mix(Medium, 0.25, Tick(0.00, 329.6, 0.6), Tick(0.07, 440.0, 0.65));
                case SoundCue.Deafen:         // Lower, rounder, falling.
                    return Mix(Medium, 0.35, Note(0.00, 349.2, 0.18, 0.7, 0.05), Note(0.08, 261.6, 0.26, 0.75, 0.05));
                case SoundCue.Undeafen:       // Lower, rounder, rising.
                    return Mix(Medium, 0.35, Note(0.00, 261.6, 0.18, 0.7, 0.05), Note(0.08, 349.2, 0.26, 0.75, 0.05));
                case SoundCue.Message:        // Gentle single "plink" with a soft upper note.
                    return Mix(Small, 0.45, Note(0.00, 698.5, 0.40, 0.65, 0.25), Note(0.03, 1046.5, 0.18, 0.10, 0.0));
                case SoundCue.Connected:      // Major arpeggio: you're in.
                    return Mix(Big, 0.75, Note(0.00, 392.0, 0.45, 0.65, 0.2), Note(0.08, 493.9, 0.45, 0.7, 0.2), Note(0.16, 587.3, 0.55, 0.8, 0.2));
                case SoundCue.Disconnected:   // Two low falling notes, minor feel.
                    return Mix(Big, 0.60, Note(0.00, 349.2, 0.35, 0.7, 0.1), Note(0.12, 261.6, 0.45, 0.75, 0.1));
            }
            return new float[0];
        }

        private sealed class NoteSpec
        {
            public double Start;
            public double Frequency;
            public double Duration;
            public double Level;
            public double Overtone;
            public double Attack = 0.012;
            public double DecayRate = 7.0;
        }

        private static NoteSpec Note(double start, double frequency, double duration, double level, double overtone)
        {
            NoteSpec n = new NoteSpec();
            n.Start = start;
            n.Frequency = frequency;
            n.Duration = duration;
            n.Level = level;
            n.Overtone = overtone;
            n.DecayRate = 3.2 / duration;
            return n;
        }

        /// <summary>Ears are more sensitive to higher notes, so they're played a touch quieter.</summary>
        private static double PitchWeight(double frequency)
        {
            return frequency <= 400.0 ? 1.0 : Math.Sqrt(400.0 / frequency);
        }

        private static NoteSpec Tick(double start, double frequency, double level)
        {
            NoteSpec n = Note(start, frequency, 0.09, level, 0.0);
            n.Attack = 0.005;
            n.DecayRate = 38.0;
            return n;
        }

        private static float[] Mix(double peak, double length, params NoteSpec[] notes)
        {
            int total = (int)(length * SampleRate);
            double[] buffer = new double[total];
            foreach (NoteSpec n in notes)
            {
                int start = (int)(n.Start * SampleRate);
                int count = Math.Min(total - start, (int)(n.Duration * SampleRate));
                int i;
                for (i = 0; i < count; i++)
                {
                    double t = (double)i / SampleRate;
                    double attack = t < n.Attack ? t / n.Attack : 1.0;
                    double release = Math.Min(1.0, (count - i) / (0.012 * SampleRate)); // 12 ms fade-out
                    double envelope = attack * release * Math.Exp(-n.DecayRate * t);
                    double phase = 2.0 * Math.PI * n.Frequency * t;
                    // Sine body + a quieter, faster-decaying overtone (2.76x: a bell-like partial).
                    double tone = Math.Sin(phase) + 0.45 * n.Overtone * Math.Exp(-8.0 * t) * Math.Sin(phase * 2.0);
                    buffer[start + i] += n.Level * PitchWeight(n.Frequency) * envelope * tone;
                }
            }

            // Gentle one-pole low-pass: rounds off the harsh top end.
            double alpha = 1.0 - Math.Exp(-2.0 * Math.PI * LowPassHz / SampleRate);
            double state = 0.0;
            int k;
            for (k = 0; k < total; k++)
            {
                state += alpha * (buffer[k] - state);
                buffer[k] = state;
            }

            double max = 1e-9;
            double energy = 0.0;
            int active = 0;
            for (k = 0; k < total; k++)
            {
                max = Math.Max(max, Math.Abs(buffer[k]));
                if (Math.Abs(buffer[k]) > 1e-4)
                {
                    energy += buffer[k] * buffer[k];
                    active++;
                }
            }
            double rms = Math.Sqrt(energy / Math.Max(1, active));
            float[] output = new float[total];
            double scale = Math.Min(peak / Math.Max(rms, 1e-9), PeakCap / max);
            for (k = 0; k < total; k++)
                output[k] = (float)(buffer[k] * scale);
            return output;
        }

        private static byte[] ToPcm(float[] samples)
        {
            byte[] pcm = new byte[samples.Length * 2];
            int i;
            for (i = 0; i < samples.Length; i++)
            {
                int v = (int)Math.Round(samples[i] * 32767.0);
                if (v > 32767) v = 32767;
                if (v < -32768) v = -32768;
                pcm[i * 2] = (byte)(v & 0xFF);
                pcm[i * 2 + 1] = (byte)((v >> 8) & 0xFF);
            }
            return pcm;
        }

        /// <summary>Writes a cue as a standard .wav file (used to preview and test the sounds).</summary>
        public static void WriteWav(SoundCue cue, string path)
        {
            byte[] pcm = Render(cue);
            using (BinaryWriter w = new BinaryWriter(File.Create(path)))
            {
                w.Write(new char[] { 'R', 'I', 'F', 'F' });
                w.Write(36 + pcm.Length);
                w.Write(new char[] { 'W', 'A', 'V', 'E', 'f', 'm', 't', ' ' });
                w.Write(16);
                w.Write((short)1);
                w.Write((short)1);
                w.Write(SampleRate);
                w.Write(SampleRate * 2);
                w.Write((short)2);
                w.Write((short)16);
                w.Write(new char[] { 'd', 'a', 't', 'a' });
                w.Write(pcm.Length);
                w.Write(pcm);
            }
        }
    }
}
